-- Restores the fallacy reference list (49 entries) from the original app's
-- Fallacy.csv export. Used by the Debate Quality Report to name fallacies.
-- Re-runnable: existing names are updated in place.

ON CONFLICT (fallacy_name) DO UPDATE SET
  fallacy_type        = EXCLUDED.fallacy_type,
  fallacy_description = EXCLUDED.fallacy_description,
  fallacy_example     = EXCLUDED.fallacy_example;
